SELECT platba."Èíslo ¾ádosti o platbu",
       platba."Datum zmìny stavu",
       platba.kodwfstav "Stav ®oP" ,
       platba."Krácení dokladù provedeno",
       platba."VYUCTPLAN#Vyúètování plán" ,
       platba."VYUCTSKUT",
       platba."VYUCTPLAN#Vyúètování plán" - platba."VYUCTSKUT" AS "Zkráceno o",	
       platba."Èástka CZK dot 14f mimo MS I",
       platba."Èástka CZK dot 14f mimo MS NeI",
       platba.id

FROM  isum.v_bi_UmpPlatbaPrj platba 
-- INNER JOIN isum.v_bi_UmpRozpisFin rf ON rf.id_platba = platba.id AND rf.id_ukazatel = 361356 -- øádek 10a
-- INNER JOIN isum.v_bi_UmsCisZakladni cis ON rf.id_ukazatel=cis.id
-- INNER JOIN isum.v_bi_UMSPrilohyPlatba priloha ON priloha.id_nositelpril = platba.id -- AND platba.id_wfstav = 171855



WHERE platba.id_wfstav = 171855
AND trunc(platba."Datum zmìny stavu") < to_date('2023-01-01','yyyy-mm-dd')
AND trunc(platba."Datum zmìny stavu") >= to_date('2022-01-01','yyyy-mm-dd')



----------------------------------------
SELECT LISTAGG( priloha.nazevpril, '; ') "Název pøíloh",
       priloha.id_nositelpril
FROM isum.v_bi_UMSPrilohyPlatba priloha 

WHERE UPPER(priloha.nazevpril) like '%KRACENI%' OR
UPPER(priloha.nazevpril) like '%KRÁCENÍ%' OR
UPPER(priloha.nazevpril) like '%MINISTR%'

GROUP BY priloha.id_nositelpril







